function solve({config,state,event}){
 const c=config;
 if(state===null)state={v:c.initial,d:String(c.initial),e:null,x:false};
 let s={v:state.v,d:state.d,e:state.e,x:state.x};
 const canon=()=>{s.d=String(s.v);s.e=null};
 const valid=t=>{if(!/^[+-]?\d+$/.test(t))return null;let sign=1,i=0;if(t[0]=='+'||t[0]=='-'){if(t[0]=='-')sign=-1;i=1}let n=0;for(;i<t.length;i++){n=n*10+(t.charCodeAt(i)-48);if(!Number.isSafeInteger(n))return null}n*=sign;return Number.isSafeInteger(n)?n:null};
 if(event.type==='mode')s.x=event.disabled;
 else if(event.type==='cancel')canon();
 else if(!s.x&&event.type==='input'){s.d=event.text;s.e=null}
 else if(!s.x&&event.type==='commit'){
  let n=valid(s.d);if(n===null)s.e='invalid';else{let q=(n-c.min)/c.step,k=Math.floor(q),a=c.min+k*c.step,b=a+c.step;if(k<0)s.v=c.min;else if(a>=c.max)s.v=c.max;else if(b>c.max)s.v=a;else s.v=(n-a<=b-n)?a:b;canon()}
 }
 else if(!s.x&&event.type==='step'){
  let k=Math.round((s.v-c.min)/c.step)+(event.direction<0?-1:1),last=Math.floor((c.max-c.min)/c.step);if(k<0)k=0;if(k>last)k=last;s.v=c.min+k*c.step;canon()
 }
 return {state:s,output:{value:s.v,draft:s.d,dirty:s.d!==String(s.v),error:s.e,disabled:s.x}};
}
